"""SettlementAuditAgent — generated by G2C (e2a_inherited); hooks implemented by hand; on the
E2A v1.2 hooks since the v1.3 preparation (each hook declares what it uses: state, ctx).

Explains a finding the deterministic rules already made, grounded in the
retrieved policy clauses. run() is inherited from E2A's BaseAgent and is never
overridden: apply policy -> build messages -> infer through config['llm_service']
-> evaluate (groundedness) -> fallback below the confidence threshold.
"""
import logging

from e2a import BaseAgent

from ..services.llm import AGENT_MARKER
from ..services.policy_rag import PolicyRAGPipeline


class SettlementAuditAgent(BaseAgent):
    """Inherits the public entry point and every NFR from BaseAgent.
    Input validation is a _validate_settlement_audit_agent validator on the
    BaseValidationService subclass; the model is reached only through
    config['llm_service']."""
    agent_name = 'SettlementAuditAgent'

    def __init__(self, rag: PolicyRAGPipeline) -> None:
        self.rag = rag

    def _build_messages(self, state, ctx) -> list:
        s = state['settlement']
        lines = [f"Settlement: {s['settlement_id']} ({s['amount']} {s['currency']}, "
                 f"{s['payer_account']} -> {s['payee_account']}, {s['status']})", "Rule hits:"]
        lines += [f"- RULE {h['rule']} ({h['policy_id']}): {h['detail']}" for h in state['rule_hits']]
        lines.append("Policies:")
        lines += [f"[{p['policy_id']}] {p['text']}" for p in state['policies']]
        return [{'role': 'system', 'content': f'You are the {AGENT_MARKER}. Explain why the settlement was '
                                              'flagged, citing only the policies given.'},
                {'role': 'user', 'content': '\n'.join(lines)}]

    def _apply_policy(self, state, ctx) -> None:
        if not ctx.tenant_id:
            raise PermissionError('a tenant is required')
        if not state.get('rule_hits'):
            raise ValueError('the agent only explains flagged settlements')

    def _evaluate_output(self, response, state, ctx) -> float:
        text = (response or {}).get('text', '') if isinstance(response, dict) else str(response or '')
        score = self.rag.groundedness(text, [p['policy_id'] for p in state['policies']])
        state['groundedness'] = score
        return score

    def _fallback(self, state, ctx):
        details = '; '.join(f"{h['rule']}: {h['detail']} ({h['policy_id']})" for h in state['rule_hits'])
        return {'text': f"Flagged by rules: {details}.", 'degraded': True}

    def _handle_error(self, error, state, ctx):
        logging.error(f'[{self.agent_name}] {error}')
        state.setdefault('errors', []).append(str(error))
        state['response'] = self._fallback(state, ctx)        # explain from the rules alone
        return state
